---
/**
 * @title Callout
 * @level liftoff
 * @description Themed documentation callout with a semantic label and non-color type marker.
 * @category Documentation
 * @hydration none
 * @accessibility
 * - Renders `<aside>` with an accessible label; type is conveyed in text, not color alone.
 * @keyboard
 * - No custom keyboard behavior.
 * @slots
 * - `default`: Callout body.
 */

import type { HTMLAttributes } from "astro/types";
import "./docs.css";

type Props = Omit<HTMLAttributes<"aside">, "aria-label"> & {
  type?: "note" | "warning" | "tip";
  title?: string;
};
const { type = "note", title } = Astro.props as Props;

---

<aside data-lsui-callout data-type={type} aria-label={title ?? type} {...Astro.props}>
  {title && <strong>{title}</strong>}
  <slot />
</aside>

/* LightSpeedUI Level 2 — documentation chrome; semantic tokens only. */
@layer lsui {
  @layer components {
    [data-lsui-callout] {
      box-sizing: border-box;
      margin-block: var(--space-md);
      padding: var(--space-md);
      border: var(--border-width) solid var(--color-border-strong);
      border-inline-start: var(--border-width-lg, 3px) solid var(--color-ring);
      border-radius: var(--radius-md);
      background: var(--color-surface);
      color: var(--color-text);
    }

    [data-lsui-callout][data-type="warning"] {
      border-inline-start-color: var(--color-warning, var(--color-ring));
    }

    [data-lsui-callout] p:last-child {
      margin-block-end: 0;
    }

    [data-lsui-docs-sidebar] {
      font-family: var(--font-body);
      font-size: var(--text-sm);
    }

    [data-lsui-docs-sidebar] ul {
      list-style: none;
      padding-inline-start: var(--space-3);
    }

    [data-lsui-docs-sidebar] a {
      display: block;
      min-block-size: var(--target-min-size, 1.5rem);
      padding-block: var(--space-1);
      color: var(--color-text-muted);
    }

    [data-lsui-docs-sidebar] a[aria-current="page"] {
      color: var(--color-text);
      font-weight: var(--weight-medium);
    }

    [data-lsui-prev-next] {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: var(--space-md);
      padding-block: var(--space-lg);
    }

    [data-lsui-prev-next] a {
      min-block-size: var(--target-min-size, 1.5rem);
      color: var(--color-text);
    }
  }
}
